<?php
$error=null;
if(request_method('POST')){try{verify_csrf();$action=post_string('action');if($action==='create'){$name=post_string('full_name');$email=strtolower(post_string('email'));$username=strtolower(post_string('username'));$roleId=(int)($_POST['role_id']??0);$password=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$roleId<1||strlen($password)<8)throw new RuntimeException('Complete all required fields; password must contain at least 8 characters.');if(!preg_match('/^[a-zA-Z0-9._-]{3,80}$/',$username))throw new RuntimeException('Username must be 3–80 characters using letters, numbers, dots, underscores or hyphens.');$roleName=(string)query_value('SELECT role_name FROM roles WHERE role_id=?',[$roleId]);if($roleName==='')throw new RuntimeException('Select a valid role.');if(in_array($roleName,['Doctor','Patient'],true))throw new RuntimeException('Create doctors from Doctor Management and patients from Patient Registration so linked profiles are also created.');db()->prepare("INSERT INTO users (role_id,full_name,username,email,password_hash,phone,account_status) VALUES (?,?,?,?,?,?,'Active')")->execute([$roleId,$name,$username,$email,password_hash($password,PASSWORD_DEFAULT),nullable(post_string('phone'))]);$id=(int)db()->lastInsertId();log_action('CREATE','users',$id,null,['role'=>$roleName]);flash('user','User account created.','success');redirect_to('users');}if($action==='toggle'){$id=(int)$_POST['user_id'];if($id===(int)current_user()['user_id'])throw new RuntimeException('You cannot disable your own account.');db()->prepare("UPDATE users SET account_status=IF(account_status='Active','Inactive','Active') WHERE user_id=?")->execute([$id]);log_action('TOGGLE_STATUS','users',$id);flash('user','User status changed.','success');redirect_to('users');}if($action==='reset'){$id=(int)$_POST['user_id'];$password=(string)($_POST['new_password']??'');if(strlen($password)<8)throw new RuntimeException('New password must contain at least 8 characters.');db()->prepare('UPDATE users SET password_hash=? WHERE user_id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$id]);log_action('ADMIN_PASSWORD_RESET','users',$id);flash('user','Password reset completed.','success');redirect_to('users');}}catch(Throwable $e){$error=$e->getMessage();}}
$roles=db()->query('SELECT * FROM roles ORDER BY role_name')->fetchAll();$rows=db()->query('SELECT u.*,r.role_name FROM users u JOIN roles r ON r.role_id=u.role_id ORDER BY u.created_at DESC')->fetchAll();
?>
<div class="page-header"><div><h2>Users & roles</h2><p>Administrative, reception and laboratory access accounts.</p></div><button class="btn btn-primary" data-modal-open="userModal">＋ Add user</button></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card"><div class="card-header"><div><h3>System users</h3><p><?=count($rows)?> accounts.</p></div><input class="input" style="max-width:260px" placeholder="Search users..." data-table-filter="usersTable"></div><div class="table-wrap"><table class="data-table" id="usersTable"><thead><tr><th>User</th><th>Role</th><th>Contact</th><th>Last login</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="table-title"><?=e($r['full_name'])?></div><div class="table-subtitle">@<?=e($r['username'])?></div></td><td><?=e($r['role_name'])?></td><td><?=e($r['email'])?><div class="table-subtitle"><?=e($r['phone']??'')?></div></td><td><?=format_date($r['last_login'],'d M Y, h:i A')?></td><td><span class="badge badge-<?=status_class($r['account_status'])?>"><?=e($r['account_status'])?></span></td><td><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="user_id" value="<?=$r['user_id']?>"><button class="btn btn-warning btn-sm" <?=$r['user_id']==current_user()['user_id']?'disabled':''?>><?=$r['account_status']==='Active'?'Disable':'Enable'?></button></form><form method="post" class="actions" onsubmit="return confirm('Reset this password?')"><?=csrf_field()?><input type="hidden" name="action" value="reset"><input type="hidden" name="user_id" value="<?=$r['user_id']?>"><input class="input" style="width:125px;padding:7px" type="password" name="new_password" placeholder="New password" minlength="8" required><button class="btn btn-light btn-sm">Reset</button></form></div></td></tr><?php endforeach;?></tbody></table></div></div><div class="modal-backdrop" id="userModal"><div class="modal"><div class="modal-header"><h3>Add system user</h3><button class="close-btn" data-modal-close>×</button></div><form method="post"><div class="modal-body"><?=csrf_field()?><input type="hidden" name="action" value="create"><div class="form-grid"><div class="field"><label class="required">Full name</label><input class="input" name="full_name" required></div><div class="field"><label class="required">Role</label><select class="select" name="role_id" required><option value="">Select role</option><?php foreach($roles as $r):?><?php if(in_array($r['role_name'],['Doctor','Patient'],true))continue;?><option value="<?=$r['role_id']?>"><?=e($r['role_name'])?></option><?php endforeach;?></select></div><div class="field"><label class="required">Email</label><input class="input" type="email" name="email" required></div><div class="field"><label class="required">Username</label><input class="input" name="username" required></div><div class="field"><label>Phone</label><input class="input" name="phone"></div><div class="field"><label class="required">Password</label><input class="input" type="password" name="password" minlength="8" required></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-modal-close>Cancel</button><button class="btn btn-primary">Create user</button></div></form></div></div>
